8	/**
9	 * Business rule: an owner's effective registration date must fall on a business day. The effective
10	 * date is the one supplied on the request, or the server's current date when none was supplied; a
11	 * Saturday or Sunday rolls forward to the following Monday. Kept as a small, self-contained unit so
12	 * the rule can be applied from the create flow before any value derived from the registration date
13	 * (membership number, per-day create limit) is computed.
14	 */
15	public final class OwnerRegistrationDatePolicy {
16	
17	    private OwnerRegistrationDatePolicy() {
18	    }
19	
20	    /** Set the owner's registrationDate to its effective business-day value. */
21	    public static void assignBusinessDayRegistrationDate(Owner owner) {
22	        LocalDate effective = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
23	        owner.setRegistrationDate(rollToBusinessDay(effective));
24	    }
25	
26	    private static LocalDate rollToBusinessDay(LocalDate date) {
27	        if (date.getDayOfWeek() == DayOfWeek.SATURDAY) {
28	            return date.plusDays(2);
29	        }
30	        if (date.getDayOfWeek() == DayOfWeek.SUNDAY) {
31	            return date.plusDays(1);
32	        }
33	        return date;
34	    }
35	}
