171	    @ExceptionHandler(OwnerDailyLimitPolicy.DailyLimitReachedException.class)
172	    @ResponseBody
173	    public ResponseEntity<ProblemDetail> handleDailyLimitReachedException(OwnerDailyLimitPolicy.DailyLimitReachedException e, HttpServletRequest request) {
174	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
175	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), "The maximum number of owners for today has already been reached");
176	        return ResponseEntity.status(status).body(detail);
177	    }
178	
179	    @ExceptionHandler(OwnerEmailPolicy.DuplicateEmailException.class)
180	    @ResponseBody
181	    public ResponseEntity<ProblemDetail> handleDuplicateEmailException(OwnerEmailPolicy.DuplicateEmailException e, HttpServletRequest request) {
182	        HttpStatus status = HttpStatus.CONFLICT;
183	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), "The email is already used by another owner");
184	        return ResponseEntity.status(status).body(detail);
185	    }
186	
187	    @ExceptionHandler(OwnerHouseholdPolicy.DuplicateHouseholdException.class)
188	    @ResponseBody
189	    public ResponseEntity<ProblemDetail> handleDuplicateHouseholdException(OwnerHouseholdPolicy.DuplicateHouseholdException e, HttpServletRequest request) {
190	        HttpStatus status = HttpStatus.CONFLICT;
191	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), "Another owner already shares this last name and address");
192	        return ResponseEntity.status(status).body(detail);
193	    }
194	
195	    @ExceptionHandler(OwnerIdentityPolicy.DuplicateIdentityException.class)
196	    @ResponseBody
197	    public ResponseEntity<ProblemDetail> handleDuplicateIdentityException(OwnerIdentityPolicy.DuplicateIdentityException e, HttpServletRequest request) {
198	        HttpStatus status = HttpStatus.CONFLICT;
199	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), "Another owner already has this identity key");
200	        return ResponseEntity.status(status).body(detail);
201	    }
202	
203	    @ExceptionHandler(MethodArgumentNotValidException.class)
204	    @ResponseBody
205	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
206	        HttpStatus status = HttpStatus.BAD_REQUEST;
207	        BindingErrorsResponse errors = new BindingErrorsResponse();
208	        BindingResult bindingResult = e.getBindingResult();
209	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
210	        if (bindingResult.hasErrors()) {
211	            errors.addAllErrors(bindingResult);
212	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
213	                .map(fieldError -> {
214	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
215	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
216	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
217	                        fieldError.getField(),
218	                        defaultMessage,
219	                        rejectedValue);
220	                    return new ValidationMessageDto(message)
221	                        .putAdditionalProperty("field", fieldError.getField())
